        }
    );

    // Insert button in the right toolbar area
    insert_button_in_toolbar(listview, appointmentHistoryBtn);
}

function insert_button_in_toolbar(listview, button) {
    let toolbar_inserted = false;

    // Method 1: Find the Add button area and insert before it
    let addButton = listview.page.wrapper.find('.btn:contains("Add Patient Appointment")');
    if (addButton.length && !toolbar_inserted) {
        addButton.before(button);
        toolbar_inserted = true;
        console.log('Button inserted before Add button');
    }

    // Method 2: Find the primary action area
    if (!toolbar_inserted) {
        let primaryActions = listview.page.wrapper.find('.page-head .btn-primary').parent();
        if (primaryActions.length) {
            button.prependTo(primaryActions);
            toolbar_inserted = true;
            console.log('Button inserted in primary actions area');
        }
    }

    // Method 3: Find any button group in page head
    if (!toolbar_inserted) {
        let buttonGroup = listview.page.wrapper.find('.page-head .btn-group, .page-head .pull-right').first();
        if (buttonGroup.length) {
            buttonGroup.prepend(button);
            toolbar_inserted = true;
            console.log('Button inserted in button group');
        }
    }

    // Method 4: Find the page head content and append
    if (!toolbar_inserted) {
        let pageHeadContent = listview.page.wrapper.find('.page-head-content').first();
        if (pageHeadContent.length) {
            let btnContainer = $('<div class="pull-right" style="margin-left: 15px;"></div>');
            btnContainer.append(button);
            pageHeadContent.append(btnContainer);
            toolbar_inserted = true;
            console.log('Button inserted in page head content');
        }
    }

    // Method 5: Fallback - insert in page head
    if (!toolbar_inserted) {
        let pageHead = listview.page.wrapper.find('.page-head').first();
        if (pageHead.length) {
            let btnContainer = $('<div class="pull-right" style="position: absolute; top: 10px; right: 20px;"></div>');
            btnContainer.append(button);
            pageHead.append(btnContainer);
            toolbar_inserted = true;
            console.log('Button inserted in page head fallback');
        }
    }

    if (!toolbar_inserted) {
        console.log('Could not insert button in toolbar');
    }
}

// Handle appointment history action
function handle_appointment_history_action(listview) {
    console.log('Appointment History button clicked');

    // Get selected items
    let selected_items = [];
    try {
        if (listview && listview.get_checked_items) {
            selected_items = listview.get_checked_items();
        }
    } catch (e) {
        console.log('Error getting selected items:', e);
    }

    if (selected_items && selected_items.length > 0) {
        // Show prompt to choose action
        frappe.prompt([
            {
                fieldname: 'action_type',
                label: __('Choose Action'),
                fieldtype: 'Select',
                options: 'Show History for Selected Patient\nSelect Different Patient',
                reqd: 1,
                default: 'Show History for Selected Patient'
            }
        ],
        function(values) {
            if (values.action_type === 'Show History for Selected Patient') {
                let patient = selected_items[0].patient;
                if (patient) {
                    frappe.show_alert({
                        message: __('Loading detailed history for: {0}', [selected_items[0].patient_name || patient]),
                        indicator: 'blue'
                    });
                    show_detailed_appointment_history(patient);
                } else {
                    frappe.msgprint(__('Selected appointment has no patient assigned'));
                }
            } else {
                show_patient_selection_dialog();
            }
        },
        __('Appointment History Action'),
        __('Continue')
        );
    } else {
        // No selection - show patient selection dialog
        show_patient_selection_dialog();
    }
}

// Enhanced patient selection dialog
function show_patient_selection_dialog() {
    let dialog = new frappe.ui.Dialog({
        title: __('Select Patient for Detailed Appointment History'),
        size: 'small',
        fields: [
            {
                fieldtype: 'HTML',
                fieldname: 'intro_html',
                options: '<div style="text-align: center; padding: 25px; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); border-radius: 12px; color: white; margin-bottom: 25px; box-shadow: 0 4px 15px rgba(0,0,0,0.1);">' +
                    '<i class="fa fa-history fa-3x" style="margin-bottom: 15px; opacity: 0.9;"></i>' +
                    '<h4 style="margin-bottom: 10px; font-weight: 600;">Patient Appointment History</h4>' +
                    '<p style="margin: 0; opacity: 0.9; font-size: 14px;">View comprehensive appointment history with detailed statistics and beautiful visualization</p>' +
                    '</div>'
            },
            {
                fieldtype: 'Link',
                fieldname: 'patient',
                label: __('Select Patient'),
                options: 'Patient',
                reqd: 1,
                description: __('Choose a patient to view their detailed appointment history with statistics and analytics'),
                get_query: function() {
                    return {
                        filters: [
                            ['Patient', 'status', '=', 'Active']
                        ]
                    };
                }
            }
        ],
        primary_action_label: __('View Detailed History'),
        primary_action: function(values) {
            if (!values.patient) {
                frappe.msgprint(__('Please select a patient'));
                return;
            }
            dialog.hide();
            show_detailed_appointment_history(values.patient);
        }
    });

    dialog.show();
    setTimeout(() => dialog.fields_dict.patient.$input.focus(), 300);
}

// Show detailed appointment history using the enhanced backend
function show_detailed_appointment_history(patient) {
    frappe.call({
        method: 'healthcare.healthcare.doctype.patient_appointment.patient_appointment_history.get_patient_appointment_history',
        args: { patient: patient },
        callback: function(r) {
            if (r.message) {
                render_detailed_history_dialog(r.message);
            } else {
                frappe.msgprint({
                    title: __('No Data'),
                    message: __('No appointment history found for this patient'),
                    indicator: 'yellow'
                });
            }
        },
        error: function(r) {
            frappe.msgprint({
                title: __('Error'),
                message: __('Failed to load appointment history. Please try again.'),
                indicator: 'red'
            });
        },
        freeze: true,
        freeze_message: __('Loading detailed appointment history...')
    });
}

