function handle_history_action(listview) {
    console.log('Appointment History button clicked');

    var selected_items = [];
    try {
        if (listview && listview.get_checked_items) {
            selected_items = listview.get_checked_items();
        }
    } catch (e) {
        console.log('Error getting selected items:', e);
    }

    if (selected_items && selected_items.length > 0) {
        if (selected_items.length > 1) {
            frappe.msgprint({
                title: __('Multiple Appointments Selected'),
                message: __('Please select only one appointment to view patient history. Currently {0} appointments are selected.', [selected_items.length]),
                indicator: 'orange'
            });
            return;
        }

        var patient = selected_items[0].patient;
        if (patient) {
            show_patient_history(patient);
        } else {
            frappe.msgprint({
                title: __('No Patient'),
                message: __('Selected appointment has no patient assigned'),
                indicator: 'red'
            });
        }
    } else {
        show_patient_selector();
    }
}

